import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Custom CUDA kernel for element-wise addition (float32) ----------
elementwise_add_kernel = """
__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}
torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float()>, size);

    return out;
}
"""

# Load the custom CUDA function for element-wise addition
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=("torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"),
    cuda_sources=elementwise_add_kernel,
    functions=["elementwise_add_cuda"],
    verbose=True,
)

# ---------- Custom CUDA kernel for transposed 3D convolution (naive) ----------
transposed_conv3d_kernel = """
__global__ void transposed_conv3d_kernel(const float* input, const float* kernel,
                                          float* output,
                                          int batch_size, int in_channels,
                                          int out_channels,
                                          int stride, int padding, int output_padding,
                                          int kernel_h, int kernel_w, int kernel_d) {
    // naive: each thread computes one output voxel.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * in_channels * out_channels * stride * stride * stride) {
        int b = idx / (in_channels * out_channels * stride * stride * stride);
        int rem = idx % (in_channels * out_channels * stride * stride * stride);
        if (b < batch_size) {
            // compute output coordinates
            int c = rem / (out_channels * stride * stride * stride);
            int d = (rem % (out_channels * stride * stride * stride)) / stride;
            int e = (rem % stride) / stride;  // dummy for square
            for (int i = 0; i < in_channels; ++i) {
                for (int ky = -kernel_h/2; ky <= kernel_h/2; ++ky) {
                    for (int kx = -kernel_w/2; kx <= kernel_w/2; ++kx) {
                        for (int kw = -kernel_d/2; kw <= kernel_d/2; ++kw) {
                            int input_idx = b * in_channels * out_channels *
                                        stride * stride * stride +
                                          i * out_channels * stride * stride * stride +
                                          c * stride * stride * stride +
                                          d * stride + e + ky * stride + kx * stride + kw;
                            output[idx] = x[input_idx];
                        }
                    }
                }
            }
        }
    }
}
torch::Tensor transposed_conv3d_cuda(torch::Tensor x, int stride=1, int padding=0,
                                       int output_padding=0, int groups=1, bool bias=false) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    transposed_conv3d_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), x.stride()? ... , out.data_ptr<float>());

    return out;
}
"""

# Load the custom CUDA function for transposed conv (placeholder)
transposed_conv3d_cuda = load_inline(
